sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float2 center;
uniform float frequency;
uniform float strength;
uniform float phase;
uniform float radius;
uniform float feather;
uniform float reach;
uniform float style;
half4 main(float2 coord) {
    float m = reach > 0.5 ? min(screen.z, screen.w) : min(size.x, size.y);
    float2 d = coord - center * size;
    float r = length(d) / m;
    if (r <= 0.0) return image.eval(coord);
    float edge = max(feather * radius, 0.0005);
    float fade = style > 0.5 ? 1.0 - smoothstep(radius * (1.0 - 0.5 * feather), radius * (1.0 + 0.5 * feather) + 0.0005, r) : 1.0 - smoothstep(radius - edge, radius, r);
    float wave = sin(6.2831853 * (frequency * r + (style > 0.5 ? phase : -phase)));
    float2 q = coord + d / (r * m) * wave * strength * m * 0.5 * fade;
    return image.eval(style > 0.5 ? clamp(q, screen.xy + 0.5, screen.xy + screen.zw - 0.5) : q);
}
